files.Particle.spx:
var (
 phase float64
)
onCloned data => {
 spawned++
 phase = float64(data.(int))
 setXYpos (float64(data.(int)%30)-15)*24, (float64(data.(int)/30)-5)*24
 setGraphicEffect GhostEffect, 35
 show
 for {
  dt := waitNextFrame()
  changeXpos 35 * float64(dt)
  if xpos > 450 { setXpos -450 }
 }
}

files.main.spx:
var (
 spawned int
)
onStart => {
 for i:=0; i<50; i++ {
  Particle.clone i
  if i % 10 == 9 { waitNextFrame() }
 }
 wait 0.2
 println "PROBE CLONES", 50, spawned
 wait 0.5
println "PROBE SAMPLE", currentFrame(), timer
wait 1
println "PROBE SAMPLE", currentFrame(), timer
wait 1
println "PROBE SAMPLE", currentFrame(), timer
wait 1
println "PROBE SAMPLE", currentFrame(), timer
println "PROBE DONE"
}

